import{z as s,x as m,o as E,c as B,q as r,j as A,D as e,d as l,s as t,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Omni 模型对齐","description":"","frontmatter":{"title":"Omni 模型对齐","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/omni-model-alignment.md","filePath":"llm/omni-model-alignment.md","lastUpdated":1791063341000}'),d={name:"llm/omni-model-alignment.md"};function p(T,a,C,h,D,c){const i=m("Mermaid");return E(),B("div",null,[a[2]||(a[2]=r('<h1 id="omni-模型对齐" tabindex="-1">Omni 模型对齐 <a class="header-anchor" href="#omni-模型对齐" aria-label="Permalink to &quot;Omni 模型对齐&quot;">​</a></h1><div class="epigraph"><p>看、听、说、写进同一权重之后，对齐不再是单模态 RLHF。拒绝一张图、一段声、一句字，必须是同一套策略。</p><footer>—— 对照 Qwen2.5-Omni 等 Thinker–Talker 叙述；指令与安全仍落在共享语言骨干上</footer></div><p><a href="/llm/music-generation">上一课</a>与语音、图像生成器可以各训各的。缺口是 omni：多路编码器进共享 LLM，多路解码器出，训练混合与安全策略要一起定。后课音画同步是其中最硬的时间对齐，不替代本课的策略对齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/llava-projector">LLaVA 投影器</a> 只接一路视觉。<a href="/llm/clip">CLIP</a> 只拉图文。Omni 还要音频编码器、可选视觉生成头、语音出。Qwen2.5-Omni 把 Thinker（多模态理解 + 文本）与 Talker（流式语音出）分开，避免语音解码打乱语言隐状态。对齐问题变成：哪一路允许更新 LLM、如何混合损失、有害图像与有害语音是否共用拒答模板。</p><p>若视觉 SFT 与语音 SFT 分阶段且不回放，后训会洗掉先训的模态——和统一理解生成里「一种损失主导」相同。</p><p><span class="marginnote">输入侧越 omni，越要防跨模态越狱：图里写指令、音频里说覆盖系统提示。文本安全层看不见这些通道。</span></p><p><span class="marginnote">Thinker–Talker 就是把「想」和「说」拆成两个模块的手段：Thinker 负责理解输入并产出文本，Talker 负责把文本变成流畅语音。类比一个人先在心里打草稿、再开口念——分开后，学说话不会干扰学思考。</span></p><p><span class="marginnote">「后训洗掉先训」即灾难性遗忘：假设视觉 SFT 占 10 万步、语音 SFT 占 10 万步且不混旧数据，语音阶段结束时视觉任务的准确率可能从 80% 掉回 30%。初学者容易以为「多训一种模态只会加分」，实际上不回放旧数据就是在覆盖。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构上声明共享与分离（Thinker/Talker、双塔视觉）。训练：模态混合比例、指令模板跨模态一致、安全数据覆盖图/声/文。评测：各模态任务分列 + 跨模态一致性（同一问题用图问与用嘴问是否同策略）+ 越狱。不要用纯文本偏好模型直接给语音打分而不听。</p>',11)),(E(),A(o,null,{default:e(()=>[t(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%A7%86%E8%A7%89%22%5D%20--%3E%20TH%5B%22%E5%85%B1%E4%BA%AB%E7%90%86%E8%A7%A3%E9%AA%A8%E5%B9%B2%22%5D%0A%20%20A%5B%22%E9%9F%B3%E9%A2%91%22%5D%20--%3E%20TH%0A%20%20T%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20TH%0A%20%20TH%20--%3E%20TXT%5B%22%E6%96%87%E6%9C%AC%E5%87%BA%22%5D%0A%20%20TH%20--%3E%20SPK%5B%22%E8%AF%AD%E9%9F%B3%E5%87%BA%E5%A4%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[l("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"共享骨干让跨模态指代（「你刚才听到的那个，看图里有没有」）走同一套上下文。分离的 Talker 保护流式声学不回流污染文本推理。对齐损失若只加在文本，语音出可以念出文本已拒绝的内容——必须在出声头上也约束，或强制语音与已对齐文本一致。",-1)),(E(),A(o,null,{default:e(()=>[t(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%9C%89%E5%AE%B3%E9%97%AE%E9%A2%98%22%5D%20--%3E%20TXTDEC%7B%22%E6%96%87%E6%9C%AC%20Thinker%20%E5%88%A4%E6%96%AD%22%7D%0A%20%20TXTDEC%20--%3E%7C%22%E6%96%87%E6%9C%AC%E6%8B%92%E7%BB%9D%22%7C%20REJ%5B%22%E8%BE%93%E5%87%BA%E6%8B%92%E7%AD%94%E6%96%87%E6%9C%AC%22%5D%0A%20%20TXTDEC%20--%3E%7C%22%E6%96%87%E6%9C%AC%E5%9B%9E%E7%AD%94%22%7C%20ANS%5B%22%E8%BE%93%E5%87%BA%E6%AD%A3%E5%B8%B8%E5%9B%9E%E7%AD%94%22%5D%0A%20%20REJ%20--%3E%20SPK%5B%22Talker%20%E8%AF%AD%E9%9F%B3%E5%87%BA%E5%A4%B4%22%5D%0A%20%20SPK%20--%3E%20CHK%7B%22%E8%AF%AD%E9%9F%B3%E4%BE%A7%E6%98%AF%E5%90%A6%E5%90%8C%E6%A0%B7%E8%A2%AB%E7%BA%A6%E6%9D%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20LEAK%5B%22%E8%AF%AD%E9%9F%B3%E5%BF%B5%E5%87%BA%E8%A2%AB%E6%8B%92%E5%86%85%E5%AE%B9%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20SAFE%5B%22%E8%AF%AD%E9%9F%B3%E5%90%8C%E6%A0%B7%E6%8B%92%E7%AD%94%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">这张图回答的问题是：为什么「文本层已拒答」还不够。可以把它想象成审稿流程——正文被毙了，但朗读版还在照原稿念，等于白拒。所以约束必须同时挂在文本出与语音出两条头上，或强制语音逐字跟随已对齐的文本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>策略对齐不等于时间戳对齐。下一课专门钉口型、节拍与音画同步。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Omni 对齐是混合训练、拒答模板与跨模态越狱，不只是接更多编码器。</li><li>语音出头必须纳入约束，否则会念出文本已拒的内容。</li><li>评测要分列模态并做跨模态一致性。</li><li>出处：Qwen2.5-Omni 等 omni 系统叙述；投影与对比见 LLaVA / CLIP。</li></ul>',5))])}const k=s(d,[["render",p]]);export{f as __pageData,k as default};
